export default JSON.parse("{\"workId\":\"zhuangzi\",\"chapter\":{\"id\":\"zhuangzi_ch-33\",\"workId\":\"zhuangzi\",\"order\":33,\"title\":\"天下第三十三\",\"difficulty\":4,\"estimatedMinutes\":11,\"passageIds\":[\"zhuangzi_ch-33_p-1\",\"zhuangzi_ch-33_p-2\",\"zhuangzi_ch-33_p-3\",\"zhuangzi_ch-33_p-4\",\"zhuangzi_ch-33_p-5\",\"zhuangzi_ch-33_p-6\",\"zhuangzi_ch-33_p-7\",\"zhuangzi_ch-33_p-8\",\"zhuangzi_ch-33_p-9\",\"zhuangzi_ch-33_p-10\",\"zhuangzi_ch-33_p-11\",\"zhuangzi_ch-33_p-12\",\"zhuangzi_ch-33_p-13\",\"zhuangzi_ch-33_p-14\",\"zhuangzi_ch-33_p-15\",\"zhuangzi_ch-33_p-16\",\"zhuangzi_ch-33_p-17\",\"zhuangzi_ch-33_p-18\",\"zhuangzi_ch-33_p-19\",\"zhuangzi_ch-33_p-20\",\"zhuangzi_ch-33_p-21\",\"zhuangzi_ch-33_p-22\",\"zhuangzi_ch-33_p-23\",\"zhuangzi_ch-33_p-24\",\"zhuangzi_ch-33_p-25\",\"zhuangzi_ch-33_p-26\",\"zhuangzi_ch-33_p-27\",\"zhuangzi_ch-33_p-28\",\"zhuangzi_ch-33_p-29\",\"zhuangzi_ch-33_p-30\",\"zhuangzi_ch-33_p-31\",\"zhuangzi_ch-33_p-32\",\"zhuangzi_ch-33_p-33\",\"zhuangzi_ch-33_p-34\",\"zhuangzi_ch-33_p-35\",\"zhuangzi_ch-33_p-36\",\"zhuangzi_ch-33_p-37\",\"zhuangzi_ch-33_p-38\",\"zhuangzi_ch-33_p-39\",\"zhuangzi_ch-33_p-40\",\"zhuangzi_ch-33_p-41\",\"zhuangzi_ch-33_p-42\",\"zhuangzi_ch-33_p-43\",\"zhuangzi_ch-33_p-44\",\"zhuangzi_ch-33_p-45\",\"zhuangzi_ch-33_p-46\",\"zhuangzi_ch-33_p-47\",\"zhuangzi_ch-33_p-48\",\"zhuangzi_ch-33_p-49\",\"zhuangzi_ch-33_p-50\",\"zhuangzi_ch-33_p-51\",\"zhuangzi_ch-33_p-52\",\"zhuangzi_ch-33_p-53\",\"zhuangzi_ch-33_p-54\",\"zhuangzi_ch-33_p-55\",\"zhuangzi_ch-33_p-56\",\"zhuangzi_ch-33_p-57\",\"zhuangzi_ch-33_p-58\",\"zhuangzi_ch-33_p-59\",\"zhuangzi_ch-33_p-60\"],\"tags\":[]},\"passages\":[{\"id\":\"zhuangzi_ch-33_p-1\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":1,\"canonicalText\":\"天下之治方術者多矣，皆以其有為不可加矣。古之所謂道術者，果惡乎在？曰：「無乎不在。」\",\"sentenceIds\":[\"zhuangzi_ch-33_p-1_s-1\",\"zhuangzi_ch-33_p-1_s-2\",\"zhuangzi_ch-33_p-1_s-3\",\"zhuangzi_ch-33_p-1_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 1 節）中描繪道：自然天道法則下的治方術的人或自然天道法則地萬物多矣，皆以他的有為不可加矣。古的所謂大道自然之理術的人或自然天道法則地萬物，果惡乎在？說大道自然之理：：無乎不在。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 1 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「天下之治方術者多矣，皆以其有為不可加矣」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「天下之治方術者多矣，皆以其有為不可加矣。古之所謂道術……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-2\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":2,\"canonicalText\":\"曰：「神何由降？明何由出？」「聖有所生，王有所成，皆原於一。」\",\"sentenceIds\":[\"zhuangzi_ch-33_p-2_s-1\",\"zhuangzi_ch-33_p-2_s-2\",\"zhuangzi_ch-33_p-2_s-3\",\"zhuangzi_ch-33_p-2_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 2 節）中描繪道：說大道自然之理：：神何由降？明何由出？聖有所生，王有所成，皆原於一。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 2 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「曰：「神何由降」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「曰：「神何由降？明何由出？」「聖有所生，王有所成，皆……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-3\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":3,\"canonicalText\":\"不離於宗，謂之天人。不離於精，謂之神人。不離於真，謂之至人。以天為宗，以德為本，以道為門，兆於變化，謂之聖人。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-3_s-1\",\"zhuangzi_ch-33_p-3_s-2\",\"zhuangzi_ch-33_p-3_s-3\",\"zhuangzi_ch-33_p-3_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 3 節）中描繪道：不離於宗，謂的自然天道法則人。不離於精，謂的神人。不離於真，謂的至人。以自然天道法則為宗，以自然玄德之境為本，以大道自然之理為門，兆於變化，謂的體悟大道之至人聖哲。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 3 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「不離於宗，謂之天人」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「不離於宗，謂之天人。不離於精，謂之神人。不離於真，謂……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-4\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":4,\"canonicalText\":\"以仁為恩，以義為理，以禮為行，以樂為和，薰然慈仁，謂之君子。以法為分，以名為表，以操為驗，以稽為決，其數一二三四是也，百官以此相齒，\",\"sentenceIds\":[\"zhuangzi_ch-33_p-4_s-1\",\"zhuangzi_ch-33_p-4_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 4 節）中描繪道：以仁為恩，以義為理，以禮為行，以樂為和，薰然慈仁，謂的明達修養之君子賢士。以法為分，以名為表，以操為驗，以稽為決，他的數一二三四是啊，百官以此相齒，。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 4 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「以仁為恩，以義為理，以禮為行，以樂為和，薰然慈仁，謂之君子」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「以仁為恩，以義為理，以禮為行，以樂為和，薰然慈仁，謂……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-5\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":5,\"canonicalText\":\"以事為常，以衣食為主，蕃息畜藏，老弱孤寡為意，皆有以養，民之理也。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-5_s-1\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 5 節）中描繪道：以事為常，以衣食為主，蕃息畜藏，老弱孤寡為意，皆有以養，民的理啊。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 5 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「以事為常，以衣食為主，蕃息畜藏，老弱孤寡為意，皆有以養，民之理也」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「以事為常，以衣食為主，蕃息畜藏，老弱孤寡為意，皆有以……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-6\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":6,\"canonicalText\":\"古之人其備乎！配神明，醇天地，育萬物，和天下，澤及百姓，明於本數，係於末度，六通四闢，小大精粗，其運無乎不在。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-6_s-1\",\"zhuangzi_ch-33_p-6_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 6 節）中描繪道：古的人他的備乎！配神明，醇自然天道法則地，育萬物，和自然天道法則下，澤及百姓，明於本數，係於末度，六通四闢，小大精粗，他的運無乎不在。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 6 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「古之人其備乎」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「古之人其備乎！配神明，醇天地，育萬物，和天下，澤及百……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-7\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":7,\"canonicalText\":\"其明而在數度者，舊法世傳之史尚多有之。其在於《詩》、《書》、《禮》、《樂》者，鄒魯之士搢紳先生多能明之。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-7_s-1\",\"zhuangzi_ch-33_p-7_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 7 節）中描繪道：他的明而且在數度的人或自然天道法則地萬物，舊法世傳的史尚多有的。他的在於《詩》、《書》、《禮》、《樂》的人或自然天道法則地萬物，鄒魯的士搢紳先生多能明的。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 7 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「其明而在數度者，舊法世傳之史尚多有之」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「其明而在數度者，舊法世傳之史尚多有之。其在於《詩》、……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-8\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":8,\"canonicalText\":\"《詩》以導志，《書》以導事，《禮》以導行，《樂》以導和，《易》以導陰陽，《春秋》以導名分。其數散於天下而設於中國者，百家之學時或稱而道之。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-8_s-1\",\"zhuangzi_ch-33_p-8_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 8 節）中描繪道：《詩》以導志，《書》以導事，《禮》以導行，《樂》以導和，《易》以導陰陽，《春秋》以導名分。他的數散於自然天道法則下而且設於中國的人或自然天道法則地萬物，百家的學時或稱而且大道自然之理的。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 8 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「《詩》以導志，《書》以導事，《禮》以導行，《樂》以導和，《易》以導陰陽，《春秋》以導名分」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「《詩》以導志，《書》以導事，《禮》以導行，《樂》以導……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-9\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":9,\"canonicalText\":\"天下大亂，賢聖不明，道德不一，天下多得一察焉以自好。譬如耳目鼻口，皆有所明，不能相通。猶百家眾技也，皆有所長，時有所用。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-9_s-1\",\"zhuangzi_ch-33_p-9_s-2\",\"zhuangzi_ch-33_p-9_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 9 節）中描繪道：自然天道法則下大亂，賢聖不明，大道自然之理自然玄德之境不一，自然天道法則下多得一察焉以自好。譬如耳目鼻口，皆有所明，不能相通。猶百家眾技啊，皆有所長，時有所用。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 9 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「天下大亂，賢聖不明，道德不一，天下多得一察焉以自好」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「天下大亂，賢聖不明，道德不一，天下多得一察焉以自好。……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-10\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":10,\"canonicalText\":\"雖然，不該不徧，一曲之士也。判天地之美，析萬物之理，察古人之全，寡能備於天地之美，稱神明之容。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-10_s-1\",\"zhuangzi_ch-33_p-10_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 10 節）中描繪道：雖然，不該不徧，一曲的士啊。判自然天道法則地的美，析萬物的理，察古人的全，寡能備於自然天道法則地的美，稱神明的容。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 10 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「雖然，不該不徧，一曲之士也」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「雖然，不該不徧，一曲之士也。判天地之美，析萬物之理，……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-11\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":11,\"canonicalText\":\"是故內聖外王之道，闇而不明，鬱而不發，天下之人各為其所欲焉以自為方。悲夫，百家往而不反，必不合矣！\",\"sentenceIds\":[\"zhuangzi_ch-33_p-11_s-1\",\"zhuangzi_ch-33_p-11_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 11 節）中描繪道：正因為如此內聖外王的大道自然之理，闇而且不明，鬱而且不發，自然天道法則下的人各為他的所欲焉以自為方。悲夫，百家往而且不反，必不合矣！這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 11 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「是故內聖外王之道，闇而不明，鬱而不發，天下之人各為其所欲焉以自為方」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「是故內聖外王之道，闇而不明，鬱而不發，天下之人各為其……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-12\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":12,\"canonicalText\":\"後世之學者，不幸不見天地之純，古人之大體，道術將為天下裂。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-12_s-1\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 12 節）中描繪道：後世的學的人或自然天道法則地萬物，不幸不見自然天道法則地的純，古人的大體，大道自然之理術將為自然天道法則下裂。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 12 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「後世之學者，不幸不見天地之純，古人之大體，道術將為天下裂」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「後世之學者，不幸不見天地之純，古人之大體，道術將為天……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-13\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":13,\"canonicalText\":\"不侈於後世，不靡於萬物，不暉於數度，以繩墨自矯而備世之急，古之道術有在於是者。墨翟禽滑釐聞其風而悅之，為之太過，已之大循。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-13_s-1\",\"zhuangzi_ch-33_p-13_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 13 節）中描繪道：不侈於後世，不靡於萬物，不暉於數度，以繩墨自矯而且備世的急，古的大道自然之理術有在於是的人或自然天道法則地萬物。墨翟禽滑釐聞他的風而且悅的，為的太過，已的大循。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 13 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「不侈於後世，不靡於萬物，不暉於數度，以繩墨自矯而備世之急，古之道術有在於是者」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「不侈於後世，不靡於萬物，不暉於數度，以繩墨自矯而備世……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-14\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":14,\"canonicalText\":\"作為《非樂》，命之曰《節用》；生不歌，死無服。墨子氾愛兼利而非鬭，其道不怒；又好學而博，不異，不與先王同，毀古之禮樂。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-14_s-1\",\"zhuangzi_ch-33_p-14_s-2\",\"zhuangzi_ch-33_p-14_s-3\",\"zhuangzi_ch-33_p-14_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 14 節）中描繪道：作為《絕不是樂》，命的說大道自然之理：《節用》；生不歌，死無服。墨子氾愛兼利而且絕不是鬭，他的大道自然之理不怒；又好學而且博，不異，不與先王同，毀古的禮樂。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 14 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「作為《非樂》，命之曰《節用》」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「作為《非樂》，命之曰《節用》；生不歌，死無服。墨子氾……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-15\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":15,\"canonicalText\":\"黃帝有《咸池》，堯有《大章》，舜有《大韶》，禹有《大夏》，湯有《大濩》，文王有辟雍之樂，武王周公作《武》。古之喪禮，貴賤有儀，上下有等，\",\"sentenceIds\":[\"zhuangzi_ch-33_p-15_s-1\",\"zhuangzi_ch-33_p-15_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 15 節）中描繪道：黃帝有《咸池》，堯有《大章》，舜有《大韶》，禹有《大夏》，湯有《大濩》，文王有辟雍的樂，武王周公作《武》。古的喪禮，貴賤有儀，上下有等，。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 15 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「黃帝有《咸池》，堯有《大章》，舜有《大韶》，禹有《大夏》，湯有《大濩》，文王有辟雍之樂，武王周公作《武》」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「黃帝有《咸池》，堯有《大章》，舜有《大韶》，禹有《大……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-16\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":16,\"canonicalText\":\"天子棺槨七重，諸侯五重，大夫三重，士再重。今墨子獨生不歌，死不服，桐棺三寸而無槨，以為法式。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-16_s-1\",\"zhuangzi_ch-33_p-16_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 16 節）中描繪道：自然天道法則子棺槨七重，諸侯五重，大夫三重，士再重。今墨子獨生不歌，死不服，桐棺三寸而且無槨，以為法式。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 16 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「天子棺槨七重，諸侯五重，大夫三重，士再重」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「天子棺槨七重，諸侯五重，大夫三重，士再重。今墨子獨生……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-17\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":17,\"canonicalText\":\"以此教人，恐不愛人；以此自行，固不愛己。末敗墨子道，雖然，歌而非歌，哭而非哭，樂而非樂，是果類乎？其生也勤，其死也薄，其道大觳；\",\"sentenceIds\":[\"zhuangzi_ch-33_p-17_s-1\",\"zhuangzi_ch-33_p-17_s-2\",\"zhuangzi_ch-33_p-17_s-3\",\"zhuangzi_ch-33_p-17_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 17 節）中描繪道：以此教人，恐不愛人；以此自行，固不愛己。末敗墨子大道自然之理，雖然，歌而且絕不是歌，哭而且絕不是哭，樂而且絕不是樂，是果類乎？他的生啊勤，他的死啊薄，他的大道自然之理大觳；。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 17 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「以此教人，恐不愛人」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「以此教人，恐不愛人；以此自行，固不愛己。末敗墨子道，……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-18\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":18,\"canonicalText\":\"使人憂，使人悲，其行難為也，恐其不可以為聖人之道，反天下之心，天下不堪。墨子雖獨能任，奈天下何！離於天下，其去王也遠矣。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-18_s-1\",\"zhuangzi_ch-33_p-18_s-2\",\"zhuangzi_ch-33_p-18_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 18 節）中描繪道：使人憂，使人悲，他的行難為啊，恐他的不可以為體悟大道之至人聖哲的大道自然之理，反自然天道法則下的心，自然天道法則下不堪。墨子雖獨能任，奈自然天道法則下何！離於自然天道法則下，他的去王啊遠矣。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 18 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「使人憂，使人悲，其行難為也，恐其不可以為聖人之道，反天下之心，天下不堪」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「使人憂，使人悲，其行難為也，恐其不可以為聖人之道，反……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-19\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":19,\"canonicalText\":\"墨子稱道曰：「昔者禹之湮洪水，決江河而通四夷九州也，名川三百，支川三千，小者無數。禹親自操橐耜而九雜天下之川；腓無胈，脛無毛，\",\"sentenceIds\":[\"zhuangzi_ch-33_p-19_s-1\",\"zhuangzi_ch-33_p-19_s-2\",\"zhuangzi_ch-33_p-19_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 19 節）中描繪道：墨子稱大道自然之理說大道自然之理：：昔的人或自然天道法則地萬物禹的湮洪水，決江河而且通四夷九州啊，名川三百，支川三千，小的人或自然天道法則地萬物無數。禹親自操橐耜而且九雜自然天道法則下的川；腓無胈，脛無毛，。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 19 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「墨子稱道曰：「昔者禹之湮洪水，決江河而通四夷九州也，名川三百，支川三千，小者無數」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「墨子稱道曰：「昔者禹之湮洪水，決江河而通四夷九州也，……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-20\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":20,\"canonicalText\":\"沐甚雨，櫛疾風，置萬國。禹大聖也而形勞天下也如此。」\",\"sentenceIds\":[\"zhuangzi_ch-33_p-20_s-1\",\"zhuangzi_ch-33_p-20_s-2\",\"zhuangzi_ch-33_p-20_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 20 節）中描繪道：沐甚雨，櫛疾風，置萬國。禹大聖啊而且形勞自然天道法則下啊如此。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 20 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「沐甚雨，櫛疾風，置萬國」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「沐甚雨，櫛疾風，置萬國。禹大聖也而形勞天下也如此。」」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-21\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":21,\"canonicalText\":\"使後世之墨者，多以裘褐為衣，以跂蹻為服，日夜不休，以自苦為極，曰：「不能如此，非禹之道也，不足謂墨。」\",\"sentenceIds\":[\"zhuangzi_ch-33_p-21_s-1\",\"zhuangzi_ch-33_p-21_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 21 節）中描繪道：使後世的墨的人或自然天道法則地萬物，多以裘褐為衣，以跂蹻為服，日夜不休，以自苦為極，說大道自然之理：：不能如此，絕不是禹的大道自然之理啊，不足謂墨。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 21 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「使後世之墨者，多以裘褐為衣，以跂蹻為服，日夜不休，以自苦為極，曰：「不能如此，非禹之道也，不足謂墨」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「使後世之墨者，多以裘褐為衣，以跂蹻為服，日夜不休，以……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-22\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":22,\"canonicalText\":\"相里勤之弟子五侯之徒，南方之墨者苦獲、已齒、鄧陵子之屬，俱誦《墨經》，而倍譎不同，相謂別墨；以堅白同異之辯相訾，以觭偶不仵之辭相應；\",\"sentenceIds\":[\"zhuangzi_ch-33_p-22_s-1\",\"zhuangzi_ch-33_p-22_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 22 節）中描繪道：相里勤的弟子五侯的徒，南方的墨的人或自然天道法則地萬物苦獲、已齒、鄧陵子的屬，俱誦《墨經》，而且倍譎不同，相謂別墨；以堅白同異的辯相訾，以觭偶不仵的辭相應；。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 22 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「相里勤之弟子五侯之徒，南方之墨者苦獲、已齒、鄧陵子之屬，俱誦《墨經》，而倍譎不同，相謂別墨」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「相里勤之弟子五侯之徒，南方之墨者苦獲、已齒、鄧陵子之……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-23\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":23,\"canonicalText\":\"以鉅子為聖人，皆願為之屍，冀得為其後世，至今不決。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-23_s-1\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 23 節）中描繪道：以鉅子為體悟大道之至人聖哲，皆願為的屍，冀得為他的後世，至今不決。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 23 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「以鉅子為聖人，皆願為之屍，冀得為其後世，至今不決」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「以鉅子為聖人，皆願為之屍，冀得為其後世，至今不決。」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-24\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":24,\"canonicalText\":\"墨翟禽滑釐之意則是，其行則非也。將使後世之墨者，必自苦以腓無胈脛無毛相進而已矣。亂之上也，治之下也。雖然，墨子真天下之好也，將求之不得也，雖枯槁不捨也。才士也夫！\",\"sentenceIds\":[\"zhuangzi_ch-33_p-24_s-1\",\"zhuangzi_ch-33_p-24_s-2\",\"zhuangzi_ch-33_p-24_s-3\",\"zhuangzi_ch-33_p-24_s-4\",\"zhuangzi_ch-33_p-24_s-5\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 24 節）中描繪道：墨翟禽滑釐的意則是，他的行則絕不是啊。將使後世的墨的人或自然天道法則地萬物，必自苦以腓無胈脛無毛相進而且已矣。亂的上啊，治的下啊。雖然，墨子真自然天道法則下的好啊，將求的不得啊，雖枯槁不捨啊。才士啊夫！這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 24 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「墨翟禽滑釐之意則是，其行則非也」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「墨翟禽滑釐之意則是，其行則非也。將使後世之墨者，必自……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-25\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":25,\"canonicalText\":\"不累於俗，不飾於物，不苟於人，不忮於眾，願天下之安寧以活民命，人我之養畢足而止，以此白心，古之道術有在於是者。宋鉼尹文聞其風而悅之，\",\"sentenceIds\":[\"zhuangzi_ch-33_p-25_s-1\",\"zhuangzi_ch-33_p-25_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 25 節）中描繪道：不累於俗，不飾於物，不苟於人，不忮於眾，願自然天道法則下的安寧以活民命，人我的養畢足而且止，以此白心，古的大道自然之理術有在於是的人或自然天道法則地萬物。宋鉼尹文聞他的風而且悅的，。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 25 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「不累於俗，不飾於物，不苟於人，不忮於眾，願天下之安寧以活民命，人我之養畢足而止，以此白心，古之道術有在於是者」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「不累於俗，不飾於物，不苟於人，不忮於眾，願天下之安寧……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-26\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":26,\"canonicalText\":\"作為華山之冠以自表，接萬物以別宥為始；語心之容，命之曰心之行，以聏合驩，以調海內，請欲置之以為主。見侮不辱，救民之鬭，禁攻寢兵，救世之戰。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-26_s-1\",\"zhuangzi_ch-33_p-26_s-2\",\"zhuangzi_ch-33_p-26_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 26 節）中描繪道：作為華山的冠以自表，接萬物以別宥為始；語心的容，命的說大道自然之理：心的行，以聏合驩，以調海內，請欲置的以為主。見侮不辱，救民的鬭，禁攻寢兵，救世的戰。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 26 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「作為華山之冠以自表，接萬物以別宥為始」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「作為華山之冠以自表，接萬物以別宥為始；語心之容，命之……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-27\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":27,\"canonicalText\":\"以此周行天下，上說下教，雖天下不取，強聒而不捨者也，故曰：上下見厭而強見也。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-27_s-1\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 27 節）中描繪道：以此周行自然天道法則下，上說下教，雖自然天道法則下不取，強聒而且不捨的人或自然天道法則地萬物啊，所以大道自然之理家經典評論說大道自然之理：：上下見厭而且強見啊。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 27 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「以此周行天下，上說下教，雖天下不取，強聒而不捨者也，故曰：上下見厭而強見也」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「以此周行天下，上說下教，雖天下不取，強聒而不捨者也，……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-28\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":28,\"canonicalText\":\"雖然，其為人太多，其自為太少，曰：「請欲固置五升之飯足矣。」先生恐不得飽，弟子雖飢，不忘天下，日夜不休，曰：\",\"sentenceIds\":[\"zhuangzi_ch-33_p-28_s-1\",\"zhuangzi_ch-33_p-28_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 28 節）中描繪道：雖然，他的為人太多，他的自為太少，說大道自然之理：：請欲固置五升的飯足矣。先生恐不得飽，弟子雖飢，不忘自然天道法則下，日夜不休，說大道自然之理：：。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 28 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「雖然，其為人太多，其自為太少，曰：「請欲固置五升之飯足矣」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「雖然，其為人太多，其自為太少，曰：「請欲固置五升之飯……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-29\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":29,\"canonicalText\":\"「我必得活哉！」圖傲乎救世之士哉！曰：「君子不為苛察，不以身假物。」以為無益於天下者，明之不如已也，\",\"sentenceIds\":[\"zhuangzi_ch-33_p-29_s-1\",\"zhuangzi_ch-33_p-29_s-2\",\"zhuangzi_ch-33_p-29_s-3\",\"zhuangzi_ch-33_p-29_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 29 節）中描繪道：我必得活哉！圖傲乎救世的士哉！說大道自然之理：：明達修養之君子賢士不為苛察，不以身假物。以為無益於自然天道法則下的人或自然天道法則地萬物，明的不如已啊，。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 29 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「「我必得活哉」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「「我必得活哉！」圖傲乎救世之士哉！曰：「君子不為苛察……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-30\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":30,\"canonicalText\":\"以禁攻寢兵為外，以情慾寡淺為內，其小大精粗，其行適至是而止。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-30_s-1\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 30 節）中描繪道：以禁攻寢兵為外，以情慾寡淺為內，他的小大精粗，他的行適至是而且止。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 30 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「以禁攻寢兵為外，以情慾寡淺為內，其小大精粗，其行適至是而止」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「以禁攻寢兵為外，以情慾寡淺為內，其小大精粗，其行適至……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-31\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":31,\"canonicalText\":\"公而不黨，易而無私，決然無主，趣物而不兩，不顧於慮，不謀於知，於物無擇，與之俱往，古之道術有在於是者。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-31_s-1\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 31 節）中描繪道：公而且不黨，易而且無私，決然無主，趣物而且不兩，不顧於慮，不謀於知，於物無擇，與的俱往，古的大道自然之理術有在於是的人或自然天道法則地萬物。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 31 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「公而不黨，易而無私，決然無主，趣物而不兩，不顧於慮，不謀於知，於物無擇，與之俱往，古之道術有在於是者」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「公而不黨，易而無私，決然無主，趣物而不兩，不顧於慮，……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-32\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":32,\"canonicalText\":\"彭蒙、田駢、慎到聞其風而悅之，齊萬物以為首，曰：「天能覆之，而不能載之；地能載之，而不能覆之；大道能包之，而不能辯之。知萬物皆有所可，有所不可，故曰：選則不徧，教則不至，道則無遺者矣。」\",\"sentenceIds\":[\"zhuangzi_ch-33_p-32_s-1\",\"zhuangzi_ch-33_p-32_s-2\",\"zhuangzi_ch-33_p-32_s-3\",\"zhuangzi_ch-33_p-32_s-4\",\"zhuangzi_ch-33_p-32_s-5\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 32 節）中描繪道：彭蒙、田駢、慎到聞他的風而且悅的，齊萬物以為首，說大道自然之理：：自然天道法則能覆的，而且不能載的；地能載的，而且不能覆的；大大道自然之理能包的，而且不能辯的。知萬物皆有所可，有所不可，所以大道自然之理家經典評論說大道自然之理：：選則不徧，教則不至，大道自然之理則無遺的人或自然天道法則地萬物矣。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 32 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「彭蒙、田駢、慎到聞其風而悅之，齊萬物以為首，曰：「天能覆之，而不能載之」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「彭蒙、田駢、慎到聞其風而悅之，齊萬物以為首，曰：「天……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-33\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":33,\"canonicalText\":\"是故慎到棄知去己，而緣不得已，泠汰於物以為道理，曰：「知不知，將薄知而後鄰傷之者也。」謑髁無任，而笑天下之尚賢也；縱脫無行，而非天下之大聖。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-33_s-1\",\"zhuangzi_ch-33_p-33_s-2\",\"zhuangzi_ch-33_p-33_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 33 節）中描繪道：正因為如此慎到棄知去己，而且緣不得已，泠汰於物以為大道自然之理理，說大道自然之理：：知不知，將薄知而且後鄰傷的的人或自然天道法則地萬物啊。謑髁無任，而且笑自然天道法則下的尚賢啊；縱脫無行，而且絕不是自然天道法則下的大聖。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 33 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「是故慎到棄知去己，而緣不得已，泠汰於物以為道理，曰：「知不知，將薄知而後鄰傷之者也」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「是故慎到棄知去己，而緣不得已，泠汰於物以為道理，曰：……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-34\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":34,\"canonicalText\":\"椎拍輐斷，與物宛轉，舍是與非，苟可以免，不師知慮，不知前後，魏然而已矣。推而後行，曳而後往，若飄風之還，若羽之旋，若磨石之隧，全而無非，動靜無過，未嘗有罪。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-34_s-1\",\"zhuangzi_ch-33_p-34_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 34 節）中描繪道：椎拍輐斷，與物宛轉，舍是與絕不是，苟可以免，不師知慮，不知前後，魏然而且已矣。推而且後行，曳而且後往，若飄風的還，若羽的旋，若磨石的隧，全而且無絕不是，動靜無過，未嘗有罪。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 34 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「椎拍輐斷，與物宛轉，舍是與非，苟可以免，不師知慮，不知前後，魏然而已矣」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「椎拍輐斷，與物宛轉，舍是與非，苟可以免，不師知慮，不……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-35\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":35,\"canonicalText\":\"是何故？夫無知之物，無建己之患，無用知之累，動靜不離於理，是以終身無譽。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-35_s-1\",\"zhuangzi_ch-33_p-35_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 35 節）中描繪道：是何所以？夫無知的物，無建己的患，無用知的累，動靜不離於理，是以終身無譽。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 35 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「是何故」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「是何故？夫無知之物，無建己之患，無用知之累，動靜不離……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-36\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":36,\"canonicalText\":\"故曰：至於若無知之物而已，無用賢聖，夫塊不失道。豪桀相與笑之曰：「慎到之道，非生人之行而至死人之理，適得怪焉。」\",\"sentenceIds\":[\"zhuangzi_ch-33_p-36_s-1\",\"zhuangzi_ch-33_p-36_s-2\",\"zhuangzi_ch-33_p-36_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 36 節）中描繪道：所以大道自然之理家經典評論說大道自然之理：：至於若無知的物而且已，無用賢聖，夫塊不失大道自然之理。豪桀相與笑的說大道自然之理：：慎到的大道自然之理，絕不是生人的行而且至死人的理，適得怪焉。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 36 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「故曰：至於若無知之物而已，無用賢聖，夫塊不失道」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「故曰：至於若無知之物而已，無用賢聖，夫塊不失道。豪桀……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-37\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":37,\"canonicalText\":\"田駢亦然，學於彭蒙，得不教焉。彭蒙之師曰：「古之道人，至於莫之是莫之非而已矣。其風窢然，惡可而言？」\",\"sentenceIds\":[\"zhuangzi_ch-33_p-37_s-1\",\"zhuangzi_ch-33_p-37_s-2\",\"zhuangzi_ch-33_p-37_s-3\",\"zhuangzi_ch-33_p-37_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 37 節）中描繪道：田駢亦然，學於彭蒙，得不教焉。彭蒙的師說大道自然之理：：古的大道自然之理人，至於莫的是莫的絕不是而且已矣。他的風窢然，惡可而且言？這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 37 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「田駢亦然，學於彭蒙，得不教焉」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「田駢亦然，學於彭蒙，得不教焉。彭蒙之師曰：「古之道人……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-38\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":38,\"canonicalText\":\"常反人，不聚觀，而不免於魭斷。其所謂道非道，而所言之韙不免於非。彭蒙、田駢、慎到不知道。雖然，概乎皆嘗有聞者也。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-38_s-1\",\"zhuangzi_ch-33_p-38_s-2\",\"zhuangzi_ch-33_p-38_s-3\",\"zhuangzi_ch-33_p-38_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 38 節）中描繪道：常反人，不聚觀，而且不免於魭斷。他的所謂大道自然之理絕不是大道自然之理，而且所言的韙不免於絕不是。彭蒙、田駢、慎到不知大道自然之理。雖然，概乎皆嘗有聞的人或自然天道法則地萬物啊。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 38 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「常反人，不聚觀，而不免於魭斷」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「常反人，不聚觀，而不免於魭斷。其所謂道非道，而所言之……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-39\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":39,\"canonicalText\":\"以本為精，以物為粗，以有積為不足，澹然獨與神明居，古之道術有在於是者。關尹、老聃聞其風而悅之，建之以常無有，主之以太一，以濡弱謙下為表，以空虛不毀萬物為實。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-39_s-1\",\"zhuangzi_ch-33_p-39_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 39 節）中描繪道：以本為精，以物為粗，以有積為不足，澹然獨與神明居，古的大道自然之理術有在於是的人或自然天道法則地萬物。關尹、老聃聞他的風而且悅的，建的以常無有，主的以太一，以濡弱謙下為表，以空虛不毀萬物為實。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 39 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「以本為精，以物為粗，以有積為不足，澹然獨與神明居，古之道術有在於是者」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「以本為精，以物為粗，以有積為不足，澹然獨與神明居，古……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-40\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":40,\"canonicalText\":\"關尹曰：「在己無居，形物自著。其動若水，其靜若鏡，其應若響。芴乎若亡，寂乎若清。同焉者和，得焉者失。未嘗先人而常隨人。」\",\"sentenceIds\":[\"zhuangzi_ch-33_p-40_s-1\",\"zhuangzi_ch-33_p-40_s-2\",\"zhuangzi_ch-33_p-40_s-3\",\"zhuangzi_ch-33_p-40_s-4\",\"zhuangzi_ch-33_p-40_s-5\",\"zhuangzi_ch-33_p-40_s-6\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 40 節）中描繪道：關尹說大道自然之理：：在己無居，形物自著。他的動若水，他的靜若鏡，他的應若響。芴乎若亡，寂乎若清。同焉的人或自然天道法則地萬物和，得焉的人或自然天道法則地萬物失。未嘗先人而且常隨人。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 40 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「關尹曰：「在己無居，形物自著」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「關尹曰：「在己無居，形物自著。其動若水，其靜若鏡，其……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-41\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":41,\"canonicalText\":\"老聃曰：「知其雄，守其雌，為天下谿；知其白，守其辱，為天下谷。」人皆取先，己獨取後，曰受天下之垢；\",\"sentenceIds\":[\"zhuangzi_ch-33_p-41_s-1\",\"zhuangzi_ch-33_p-41_s-2\",\"zhuangzi_ch-33_p-41_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 41 節）中描繪道：老聃說大道自然之理：：知他的雄，守他的雌，為自然天道法則下谿；知他的白，守他的辱，為自然天道法則下谷。人皆取先，己獨取後，說大道自然之理：受自然天道法則下的垢；。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 41 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「老聃曰：「知其雄，守其雌，為天下谿」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「老聃曰：「知其雄，守其雌，為天下谿；知其白，守其辱，……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-42\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":42,\"canonicalText\":\"人皆取實，己獨取虛，無藏也故有餘，巋然而有餘。其行身也，徐而不費，無為也而笑巧；\",\"sentenceIds\":[\"zhuangzi_ch-33_p-42_s-1\",\"zhuangzi_ch-33_p-42_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 42 節）中描繪道：人皆取實，己獨取虛，無藏啊所以有餘，巋然而且有餘。他的行身啊，徐而且不費，無為啊而且笑巧；。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 42 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「人皆取實，己獨取虛，無藏也故有餘，巋然而有餘」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「人皆取實，己獨取虛，無藏也故有餘，巋然而有餘。其行身……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-43\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":43,\"canonicalText\":\"人皆求福，己獨曲全，曰苟免於咎。以深為根，以約為紀，曰堅則毀矣，銳則挫矣。常寬容於物，不削於人，可謂至極。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-43_s-1\",\"zhuangzi_ch-33_p-43_s-2\",\"zhuangzi_ch-33_p-43_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 43 節）中描繪道：人皆求福，己獨曲全，說大道自然之理：苟免於咎。以深為根，以約為紀，說大道自然之理：堅則毀矣，銳則挫矣。常寬容於物，不削於人，可謂至極。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 43 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「人皆求福，己獨曲全，曰苟免於咎」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「人皆求福，己獨曲全，曰苟免於咎。以深為根，以約為紀，……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-44\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":44,\"canonicalText\":\"關尹、老聃乎！古之博大真人哉！\",\"sentenceIds\":[\"zhuangzi_ch-33_p-44_s-1\",\"zhuangzi_ch-33_p-44_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 44 節）中描繪道：關尹、老聃乎！古的博大真人哉！這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 44 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「關尹、老聃乎」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「關尹、老聃乎！古之博大真人哉！」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-45\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":45,\"canonicalText\":\"寂漠無形，變化無常，死與生與，天地並與，神明往與！芒乎何之，忽乎何適，萬物畢羅，莫足以歸，古之道術有在於是者。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-45_s-1\",\"zhuangzi_ch-33_p-45_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 45 節）中描繪道：寂漠無形，變化無常，死與生與，自然天道法則地並與，神明往與！芒乎何的，忽乎何適，萬物畢羅，莫足以歸，古的大道自然之理術有在於是的人或自然天道法則地萬物。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 45 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「寂漠無形，變化無常，死與生與，天地並與，神明往與」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「寂漠無形，變化無常，死與生與，天地並與，神明往與！芒……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-46\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":46,\"canonicalText\":\"莊周聞其風而悅之，以謬悠之說，荒唐之言，無端崖之辭，時恣縱而不儻，不以觭見之也。以天下為沈濁，不可與莊語，以巵言為曼衍，以重言為真，以寓言為廣。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-46_s-1\",\"zhuangzi_ch-33_p-46_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 46 節）中描繪道：莊周聞他的風而且悅的，以謬悠的說，荒唐的言，無端崖的辭，時恣縱而且不儻，不以觭見的啊。以自然天道法則下為沈濁，不可與莊語，以巵言為曼衍，以重言為真，以寓言為廣。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 46 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「莊周聞其風而悅之，以謬悠之說，荒唐之言，無端崖之辭，時恣縱而不儻，不以觭見之也」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「莊周聞其風而悅之，以謬悠之說，荒唐之言，無端崖之辭，……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-47\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":47,\"canonicalText\":\"獨與天地精神往來，而不敖倪於萬物，不譴是非，以與世俗處。其書雖瓌瑋，而連犿無傷也。其辭雖參差，而諔詭可觀。彼其充實不可以已，\",\"sentenceIds\":[\"zhuangzi_ch-33_p-47_s-1\",\"zhuangzi_ch-33_p-47_s-2\",\"zhuangzi_ch-33_p-47_s-3\",\"zhuangzi_ch-33_p-47_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 47 節）中描繪道：獨與自然天道法則地精神往來，而且不敖倪於萬物，不譴是絕不是，以與世俗處。他的書雖瓌瑋，而且連犿無傷啊。他的辭雖參差，而且諔詭可觀。彼他的充實不可以已，。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 47 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「獨與天地精神往來，而不敖倪於萬物，不譴是非，以與世俗處」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「獨與天地精神往來，而不敖倪於萬物，不譴是非，以與世俗……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-48\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":48,\"canonicalText\":\"上與造物者遊，而下與外死生無終始者為友。其於本也，弘大而闢，深閎而肆，其於宗也，可謂調適而上遂矣。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-48_s-1\",\"zhuangzi_ch-33_p-48_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 48 節）中描繪道：上與造物的人或自然天道法則地萬物遊，而且下與外死生無終始的人或自然天道法則地萬物為友。他的於本啊，弘大而且闢，深閎而且肆，他的於宗啊，可謂調適而且上遂矣。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 48 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「上與造物者遊，而下與外死生無終始者為友」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「上與造物者遊，而下與外死生無終始者為友。其於本也，弘……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-49\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":49,\"canonicalText\":\"雖然，其應於化而解於物也，其理不竭，其來不蛻，芒乎昧乎，未之盡者。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-49_s-1\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 49 節）中描繪道：雖然，他的應於化而且解於物啊，他的理不竭，他的來不蛻，芒乎昧乎，未的盡的人或自然天道法則地萬物。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 49 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「雖然，其應於化而解於物也，其理不竭，其來不蛻，芒乎昧乎，未之盡者」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「雖然，其應於化而解於物也，其理不竭，其來不蛻，芒乎昧……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-50\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":50,\"canonicalText\":\"惠施多方，其書五車，其道舛駁，其言也不中。歷物之意，曰：「至大無外，謂之大一；至小無內，謂之小一。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-50_s-1\",\"zhuangzi_ch-33_p-50_s-2\",\"zhuangzi_ch-33_p-50_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 50 節）中描繪道：惠施多方，他的書五車，他的大道自然之理舛駁，他的言啊不中。歷物的意，說大道自然之理：：至大無外，謂的大一；至小無內，謂的小一。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 50 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「惠施多方，其書五車，其道舛駁，其言也不中」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「惠施多方，其書五車，其道舛駁，其言也不中。歷物之意，……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-51\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":51,\"canonicalText\":\"無厚，不可積也，其大千裏。天與地卑，山與澤平。日方中方睨，物方生方死。大同而與小同異，此之謂小同異；萬物畢同畢異，此之謂大同異。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-51_s-1\",\"zhuangzi_ch-33_p-51_s-2\",\"zhuangzi_ch-33_p-51_s-3\",\"zhuangzi_ch-33_p-51_s-4\",\"zhuangzi_ch-33_p-51_s-5\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 51 節）中描繪道：無厚，不可積啊，他的大千裏。自然天道法則與地卑，山與澤平。日方中方睨，物方生方死。大同而且與小同異，此的謂小同異；萬物畢同畢異，此的謂大同異。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 51 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「無厚，不可積也，其大千裏」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「無厚，不可積也，其大千裏。天與地卑，山與澤平。日方中……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-52\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":52,\"canonicalText\":\"南方無窮而有窮，今日適越而昔來。連環可解也。我知天下之中央，燕之北越之南是也。氾愛萬物，天地一體也。」\",\"sentenceIds\":[\"zhuangzi_ch-33_p-52_s-1\",\"zhuangzi_ch-33_p-52_s-2\",\"zhuangzi_ch-33_p-52_s-3\",\"zhuangzi_ch-33_p-52_s-4\",\"zhuangzi_ch-33_p-52_s-5\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 52 節）中描繪道：南方無窮而且有窮，今日適越而且昔來。連環可解啊。我知自然天道法則下的中央，燕的北越的南是啊。氾愛萬物，自然天道法則地一體啊。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 52 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「南方無窮而有窮，今日適越而昔來」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「南方無窮而有窮，今日適越而昔來。連環可解也。我知天下……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-53\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":53,\"canonicalText\":\"惠施以此為大，觀於天下而曉辯者，天下之辯者相與樂之。卵有毛，雞三足，郢有天下，犬可以為羊，馬有卵，丁子有尾，\",\"sentenceIds\":[\"zhuangzi_ch-33_p-53_s-1\",\"zhuangzi_ch-33_p-53_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 53 節）中描繪道：惠施以此為大，觀於自然天道法則下而且曉辯的人或自然天道法則地萬物，自然天道法則下的辯的人或自然天道法則地萬物相與樂的。卵有毛，雞三足，郢有自然天道法則下，犬可以為羊，馬有卵，丁子有尾，。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 53 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「惠施以此為大，觀於天下而曉辯者，天下之辯者相與樂之」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「惠施以此為大，觀於天下而曉辯者，天下之辯者相與樂之。……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-54\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":54,\"canonicalText\":\"火不熱，山出口，輪不蹍地，目不見，指不至，至不絕，龜長於蛇，矩不方，規不可以為圓，鑿不圍枘，飛鳥之景未嘗動也，\",\"sentenceIds\":[\"zhuangzi_ch-33_p-54_s-1\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 54 節）中描繪道：火不熱，山出口，輪不蹍地，目不見，指不至，至不絕，龜長於蛇，矩不方，規不可以為圓，鑿不圍枘，飛鳥的景未嘗動啊，。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 54 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「火不熱，山出口，輪不蹍地，目不見，指不至，至不絕，龜長於蛇，矩不方，規不可以為圓，鑿不圍枘，飛鳥之景未嘗動也，」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「火不熱，山出口，輪不蹍地，目不見，指不至，至不絕，龜……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-55\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":55,\"canonicalText\":\"鏃矢之疾而有不行不止之時，狗非犬，黃馬驪牛三，白狗黑，孤駒未嘗有母，一尺之捶，日取其半，萬世不竭。辯者以此與惠施相應，終身無窮。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-55_s-1\",\"zhuangzi_ch-33_p-55_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 55 節）中描繪道：鏃矢的疾而且有不行不止的時，狗絕不是犬，黃馬驪牛三，白狗黑，孤駒未嘗有母，一尺的捶，日取他的半，萬世不竭。辯的人或自然天道法則地萬物以此與惠施相應，終身無窮。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 55 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「鏃矢之疾而有不行不止之時，狗非犬，黃馬驪牛三，白狗黑，孤駒未嘗有母，一尺之捶，日取其半，萬世不竭」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「鏃矢之疾而有不行不止之時，狗非犬，黃馬驪牛三，白狗黑……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-56\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":56,\"canonicalText\":\"桓團、公孫龍辯者之徒，飾人之心，易人之意，能勝人之口，不能服人之心，辯者之囿也。惠施日以其知與人之辯，特與天下之辯者為怪，此其柢也。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-56_s-1\",\"zhuangzi_ch-33_p-56_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 56 節）中描繪道：桓團、公孫龍辯的人或自然天道法則地萬物的徒，飾人的心，易人的意，能勝人的口，不能服人的心，辯的人或自然天道法則地萬物的囿啊。惠施日以他的知與人的辯，特與自然天道法則下的辯的人或自然天道法則地萬物為怪，此他的柢啊。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 56 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「桓團、公孫龍辯者之徒，飾人之心，易人之意，能勝人之口，不能服人之心，辯者之囿也」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「桓團、公孫龍辯者之徒，飾人之心，易人之意，能勝人之口……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-57\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":57,\"canonicalText\":\"然惠施之口談，自以為最賢，曰天地其壯乎！施存雄而無術。南方有倚人焉曰黃繚，問天地所以不墜不陷，風雨雷霆之故。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-57_s-1\",\"zhuangzi_ch-33_p-57_s-2\",\"zhuangzi_ch-33_p-57_s-3\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 57 節）中描繪道：然惠施的口談，自以為最賢，說大道自然之理：自然天道法則地他的壯乎！施存雄而且無術。南方有倚人焉說大道自然之理：黃繚，問自然天道法則地所以不墜不陷，風雨雷霆的所以。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 57 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「然惠施之口談，自以為最賢，曰天地其壯乎」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「然惠施之口談，自以為最賢，曰天地其壯乎！施存雄而無術……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-58\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":58,\"canonicalText\":\"惠施不辭而應，不慮而對，徧為萬物說，說而不休，多而無已，猶以為寡，益之以怪。以反人為實而欲以勝人為名，是以與眾不適也。\",\"sentenceIds\":[\"zhuangzi_ch-33_p-58_s-1\",\"zhuangzi_ch-33_p-58_s-2\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 58 節）中描繪道：惠施不辭而且應，不慮而且對，徧為萬物說，說而且不休，多而且無已，猶以為寡，益的以怪。以反人為實而且欲以勝人為名，是以與眾不適啊。這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 58 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「惠施不辭而應，不慮而對，徧為萬物說，說而不休，多而無已，猶以為寡，益之以怪」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「惠施不辭而應，不慮而對，徧為萬物說，說而不休，多而無……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-59\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":59,\"canonicalText\":\"弱於德，強於物，其塗隩矣。由天地之道觀惠施之能，其猶一蚊一䖟之勞者也。其於物也何庸！夫充一尚可，曰愈貴道，幾矣！\",\"sentenceIds\":[\"zhuangzi_ch-33_p-59_s-1\",\"zhuangzi_ch-33_p-59_s-2\",\"zhuangzi_ch-33_p-59_s-3\",\"zhuangzi_ch-33_p-59_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 59 節）中描繪道：弱於自然玄德之境，強於物，他的塗隩矣。由自然天道法則地的大道自然之理觀惠施的能，他的猶一蚊一䖟的勞的人或自然天道法則地萬物啊。他的於物啊何庸！夫充一尚可，說大道自然之理：愈貴大道自然之理，幾矣！這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 59 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「弱於德，強於物，其塗隩矣」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「弱於德，強於物，其塗隩矣。由天地之道觀惠施之能，其猶……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"zhuangzi_ch-33_p-60\",\"chapterId\":\"zhuangzi_ch-33\",\"order\":60,\"canonicalText\":\"惠施不能以此自寧，散於萬物而不厭，卒以善辯為名。惜乎！惠施之才，駘蕩而不得，逐萬物而不反，是窮響以聲，形與影競走也。悲夫！\",\"sentenceIds\":[\"zhuangzi_ch-33_p-60_s-1\",\"zhuangzi_ch-33_p-60_s-2\",\"zhuangzi_ch-33_p-60_s-3\",\"zhuangzi_ch-33_p-60_s-4\"],\"sourceRefs\":[{\"label\":\"《莊子》—中國哲學書電子化計劃\",\"edition\":\"郭慶藩《莊子集釋》本\",\"location\":\"https://ctext.org/zhuangzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《莊子》—維基文庫\",\"edition\":\"郭象注・成玄英疏《莊子註疏》\",\"location\":\"https://zh.wikisource.org/zh-hant/莊子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【莊子白話通譯】在《莊子・天下第三十三》（第 60 節）中描繪道：惠施不能以此自寧，散於萬物而且不厭，卒以善辯為名。惜乎！惠施的才，駘蕩而且不得，逐萬物而且不反，是窮響以聲，形與影競走啊。悲夫！這段道家哲學經典以超拔之寓言意象與深邃之思辨，闡發了順應自然、破除物執、齊一萬物與追求精神絕對自由之至高境界。\",\"analysis\":\"【莊學篇旨與寓言道境】\\\\n本段選自道家哲學巔峯鉅著《莊子》〈天下第三十三〉（第 60 節）。文本依據晉郭象注、唐成玄英疏與清郭慶藩《莊子集釋》之權威體系，生動展現了莊子「汪洋闢闔，儀態萬方」之獨特文風與哲學洞見。開篇「惠施不能以此自寧，散於萬物而不厭，卒以善辯為名」引人入勝，發人深省。\\\\n\\\\n【齊物逍遙與心性超越】\\\\n1. 寓言重言與微言大義：全段聚焦「惠施不能以此自寧，散於萬物而不厭，卒以善辯為名。惜乎……」，莊子善用「三言」（寓言、重言、巵言）之妙筆，借神話動物、自然物象與歷史寓言，破除世俗對是非、壽夭、貴賤、榮辱之狹隘分別心。\\\\n2. 心齋坐忘與精神自由：深刻體現「天地與我並生，而萬物與我為一」之齊物哲學，引導心靈超越形骸之束縛，達到「乘天地之正，而御六氣之辯，以遊無窮」之絕對逍遙之境。\\\\n\\\\n【生命美學與後世啟示】\\\\n莊子哲學以其深邃之生命關懷與超脫之宇宙情懷，深刻啟迪了魏晉玄學、唐宋詩詞與歷代文人心靈，為中華美學與東方智慧提供了最富靈性與想像力之崇高泉源。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"zhuangzi_ch-33_p-1_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-1\",\"order\":1,\"canonicalText\":\"天下之治方術者多矣，皆以其有為不可加矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-1_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-1\",\"order\":2,\"canonicalText\":\"古之所謂道術者，果惡乎在？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-1_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-1\",\"order\":3,\"canonicalText\":\"曰：「無乎不在。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-1_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-1\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-2_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-2\",\"order\":1,\"canonicalText\":\"曰：「神何由降？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-2_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-2\",\"order\":2,\"canonicalText\":\"明何由出？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-2_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-2\",\"order\":3,\"canonicalText\":\"」「聖有所生，王有所成，皆原於一。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-2_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-2\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-3_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-3\",\"order\":1,\"canonicalText\":\"不離於宗，謂之天人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-3_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-3\",\"order\":2,\"canonicalText\":\"不離於精，謂之神人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-3_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-3\",\"order\":3,\"canonicalText\":\"不離於真，謂之至人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-3_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-3\",\"order\":4,\"canonicalText\":\"以天為宗，以德為本，以道為門，兆於變化，謂之聖人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-4_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-4\",\"order\":1,\"canonicalText\":\"以仁為恩，以義為理，以禮為行，以樂為和，薰然慈仁，謂之君子。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-4_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-4\",\"order\":2,\"canonicalText\":\"以法為分，以名為表，以操為驗，以稽為決，其數一二三四是也，百官以此相齒，\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-5_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-5\",\"order\":1,\"canonicalText\":\"以事為常，以衣食為主，蕃息畜藏，老弱孤寡為意，皆有以養，民之理也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-6_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-6\",\"order\":1,\"canonicalText\":\"古之人其備乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-6_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-6\",\"order\":2,\"canonicalText\":\"配神明，醇天地，育萬物，和天下，澤及百姓，明於本數，係於末度，六通四闢，小大精粗，其運無乎不在。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-7_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-7\",\"order\":1,\"canonicalText\":\"其明而在數度者，舊法世傳之史尚多有之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-7_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-7\",\"order\":2,\"canonicalText\":\"其在於《詩》、《書》、《禮》、《樂》者，鄒魯之士搢紳先生多能明之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-8_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-8\",\"order\":1,\"canonicalText\":\"《詩》以導志，《書》以導事，《禮》以導行，《樂》以導和，《易》以導陰陽，《春秋》以導名分。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-8_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-8\",\"order\":2,\"canonicalText\":\"其數散於天下而設於中國者，百家之學時或稱而道之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-9_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-9\",\"order\":1,\"canonicalText\":\"天下大亂，賢聖不明，道德不一，天下多得一察焉以自好。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-9_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-9\",\"order\":2,\"canonicalText\":\"譬如耳目鼻口，皆有所明，不能相通。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-9_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-9\",\"order\":3,\"canonicalText\":\"猶百家眾技也，皆有所長，時有所用。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-10_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-10\",\"order\":1,\"canonicalText\":\"雖然，不該不徧，一曲之士也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-10_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-10\",\"order\":2,\"canonicalText\":\"判天地之美，析萬物之理，察古人之全，寡能備於天地之美，稱神明之容。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-11_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-11\",\"order\":1,\"canonicalText\":\"是故內聖外王之道，闇而不明，鬱而不發，天下之人各為其所欲焉以自為方。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-11_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-11\",\"order\":2,\"canonicalText\":\"悲夫，百家往而不反，必不合矣！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-12_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-12\",\"order\":1,\"canonicalText\":\"後世之學者，不幸不見天地之純，古人之大體，道術將為天下裂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-13_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-13\",\"order\":1,\"canonicalText\":\"不侈於後世，不靡於萬物，不暉於數度，以繩墨自矯而備世之急，古之道術有在於是者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-13_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-13\",\"order\":2,\"canonicalText\":\"墨翟禽滑釐聞其風而悅之，為之太過，已之大循。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-14_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-14\",\"order\":1,\"canonicalText\":\"作為《非樂》，命之曰《節用》；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-14_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-14\",\"order\":2,\"canonicalText\":\"生不歌，死無服。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-14_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-14\",\"order\":3,\"canonicalText\":\"墨子氾愛兼利而非鬭，其道不怒；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-14_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-14\",\"order\":4,\"canonicalText\":\"又好學而博，不異，不與先王同，毀古之禮樂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-15_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-15\",\"order\":1,\"canonicalText\":\"黃帝有《咸池》，堯有《大章》，舜有《大韶》，禹有《大夏》，湯有《大濩》，文王有辟雍之樂，武王周公作《武》。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-15_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-15\",\"order\":2,\"canonicalText\":\"古之喪禮，貴賤有儀，上下有等，\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-16_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-16\",\"order\":1,\"canonicalText\":\"天子棺槨七重，諸侯五重，大夫三重，士再重。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-16_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-16\",\"order\":2,\"canonicalText\":\"今墨子獨生不歌，死不服，桐棺三寸而無槨，以為法式。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-17_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-17\",\"order\":1,\"canonicalText\":\"以此教人，恐不愛人；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-17_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-17\",\"order\":2,\"canonicalText\":\"以此自行，固不愛己。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-17_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-17\",\"order\":3,\"canonicalText\":\"末敗墨子道，雖然，歌而非歌，哭而非哭，樂而非樂，是果類乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-17_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-17\",\"order\":4,\"canonicalText\":\"其生也勤，其死也薄，其道大觳；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-18_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-18\",\"order\":1,\"canonicalText\":\"使人憂，使人悲，其行難為也，恐其不可以為聖人之道，反天下之心，天下不堪。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-18_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-18\",\"order\":2,\"canonicalText\":\"墨子雖獨能任，奈天下何！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-18_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-18\",\"order\":3,\"canonicalText\":\"離於天下，其去王也遠矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-19_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-19\",\"order\":1,\"canonicalText\":\"墨子稱道曰：「昔者禹之湮洪水，決江河而通四夷九州也，名川三百，支川三千，小者無數。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-19_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-19\",\"order\":2,\"canonicalText\":\"禹親自操橐耜而九雜天下之川；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-19_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-19\",\"order\":3,\"canonicalText\":\"腓無胈，脛無毛，\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-20_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-20\",\"order\":1,\"canonicalText\":\"沐甚雨，櫛疾風，置萬國。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-20_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-20\",\"order\":2,\"canonicalText\":\"禹大聖也而形勞天下也如此。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-20_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-20\",\"order\":3,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-21_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-21\",\"order\":1,\"canonicalText\":\"使後世之墨者，多以裘褐為衣，以跂蹻為服，日夜不休，以自苦為極，曰：「不能如此，非禹之道也，不足謂墨。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-21_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-21\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-22_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-22\",\"order\":1,\"canonicalText\":\"相里勤之弟子五侯之徒，南方之墨者苦獲、已齒、鄧陵子之屬，俱誦《墨經》，而倍譎不同，相謂別墨；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-22_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-22\",\"order\":2,\"canonicalText\":\"以堅白同異之辯相訾，以觭偶不仵之辭相應；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-23_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-23\",\"order\":1,\"canonicalText\":\"以鉅子為聖人，皆願為之屍，冀得為其後世，至今不決。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-24_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-24\",\"order\":1,\"canonicalText\":\"墨翟禽滑釐之意則是，其行則非也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-24_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-24\",\"order\":2,\"canonicalText\":\"將使後世之墨者，必自苦以腓無胈脛無毛相進而已矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-24_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-24\",\"order\":3,\"canonicalText\":\"亂之上也，治之下也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-24_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-24\",\"order\":4,\"canonicalText\":\"雖然，墨子真天下之好也，將求之不得也，雖枯槁不捨也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-24_s-5\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-24\",\"order\":5,\"canonicalText\":\"才士也夫！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-25_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-25\",\"order\":1,\"canonicalText\":\"不累於俗，不飾於物，不苟於人，不忮於眾，願天下之安寧以活民命，人我之養畢足而止，以此白心，古之道術有在於是者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-25_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-25\",\"order\":2,\"canonicalText\":\"宋鉼尹文聞其風而悅之，\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-26_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-26\",\"order\":1,\"canonicalText\":\"作為華山之冠以自表，接萬物以別宥為始；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-26_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-26\",\"order\":2,\"canonicalText\":\"語心之容，命之曰心之行，以聏合驩，以調海內，請欲置之以為主。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-26_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-26\",\"order\":3,\"canonicalText\":\"見侮不辱，救民之鬭，禁攻寢兵，救世之戰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-27_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-27\",\"order\":1,\"canonicalText\":\"以此周行天下，上說下教，雖天下不取，強聒而不捨者也，故曰：上下見厭而強見也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-28_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-28\",\"order\":1,\"canonicalText\":\"雖然，其為人太多，其自為太少，曰：「請欲固置五升之飯足矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-28_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-28\",\"order\":2,\"canonicalText\":\"」先生恐不得飽，弟子雖飢，不忘天下，日夜不休，曰：\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-29_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-29\",\"order\":1,\"canonicalText\":\"「我必得活哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-29_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-29\",\"order\":2,\"canonicalText\":\"」圖傲乎救世之士哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-29_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-29\",\"order\":3,\"canonicalText\":\"曰：「君子不為苛察，不以身假物。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-29_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-29\",\"order\":4,\"canonicalText\":\"」以為無益於天下者，明之不如已也，\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-30_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-30\",\"order\":1,\"canonicalText\":\"以禁攻寢兵為外，以情慾寡淺為內，其小大精粗，其行適至是而止。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-31_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-31\",\"order\":1,\"canonicalText\":\"公而不黨，易而無私，決然無主，趣物而不兩，不顧於慮，不謀於知，於物無擇，與之俱往，古之道術有在於是者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-32_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-32\",\"order\":1,\"canonicalText\":\"彭蒙、田駢、慎到聞其風而悅之，齊萬物以為首，曰：「天能覆之，而不能載之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-32_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-32\",\"order\":2,\"canonicalText\":\"地能載之，而不能覆之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-32_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-32\",\"order\":3,\"canonicalText\":\"大道能包之，而不能辯之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-32_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-32\",\"order\":4,\"canonicalText\":\"知萬物皆有所可，有所不可，故曰：選則不徧，教則不至，道則無遺者矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-32_s-5\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-32\",\"order\":5,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-33_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-33\",\"order\":1,\"canonicalText\":\"是故慎到棄知去己，而緣不得已，泠汰於物以為道理，曰：「知不知，將薄知而後鄰傷之者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-33_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-33\",\"order\":2,\"canonicalText\":\"」謑髁無任，而笑天下之尚賢也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-33_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-33\",\"order\":3,\"canonicalText\":\"縱脫無行，而非天下之大聖。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-34_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-34\",\"order\":1,\"canonicalText\":\"椎拍輐斷，與物宛轉，舍是與非，苟可以免，不師知慮，不知前後，魏然而已矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-34_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-34\",\"order\":2,\"canonicalText\":\"推而後行，曳而後往，若飄風之還，若羽之旋，若磨石之隧，全而無非，動靜無過，未嘗有罪。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-35_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-35\",\"order\":1,\"canonicalText\":\"是何故？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-35_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-35\",\"order\":2,\"canonicalText\":\"夫無知之物，無建己之患，無用知之累，動靜不離於理，是以終身無譽。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-36_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-36\",\"order\":1,\"canonicalText\":\"故曰：至於若無知之物而已，無用賢聖，夫塊不失道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-36_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-36\",\"order\":2,\"canonicalText\":\"豪桀相與笑之曰：「慎到之道，非生人之行而至死人之理，適得怪焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-36_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-36\",\"order\":3,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-37_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-37\",\"order\":1,\"canonicalText\":\"田駢亦然，學於彭蒙，得不教焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-37_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-37\",\"order\":2,\"canonicalText\":\"彭蒙之師曰：「古之道人，至於莫之是莫之非而已矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-37_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-37\",\"order\":3,\"canonicalText\":\"其風窢然，惡可而言？\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-37_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-37\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-38_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-38\",\"order\":1,\"canonicalText\":\"常反人，不聚觀，而不免於魭斷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-38_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-38\",\"order\":2,\"canonicalText\":\"其所謂道非道，而所言之韙不免於非。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-38_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-38\",\"order\":3,\"canonicalText\":\"彭蒙、田駢、慎到不知道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-38_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-38\",\"order\":4,\"canonicalText\":\"雖然，概乎皆嘗有聞者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-39_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-39\",\"order\":1,\"canonicalText\":\"以本為精，以物為粗，以有積為不足，澹然獨與神明居，古之道術有在於是者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-39_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-39\",\"order\":2,\"canonicalText\":\"關尹、老聃聞其風而悅之，建之以常無有，主之以太一，以濡弱謙下為表，以空虛不毀萬物為實。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-40_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-40\",\"order\":1,\"canonicalText\":\"關尹曰：「在己無居，形物自著。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-40_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-40\",\"order\":2,\"canonicalText\":\"其動若水，其靜若鏡，其應若響。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-40_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-40\",\"order\":3,\"canonicalText\":\"芴乎若亡，寂乎若清。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-40_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-40\",\"order\":4,\"canonicalText\":\"同焉者和，得焉者失。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-40_s-5\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-40\",\"order\":5,\"canonicalText\":\"未嘗先人而常隨人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-40_s-6\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-40\",\"order\":6,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-41_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-41\",\"order\":1,\"canonicalText\":\"老聃曰：「知其雄，守其雌，為天下谿；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-41_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-41\",\"order\":2,\"canonicalText\":\"知其白，守其辱，為天下谷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-41_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-41\",\"order\":3,\"canonicalText\":\"」人皆取先，己獨取後，曰受天下之垢；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-42_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-42\",\"order\":1,\"canonicalText\":\"人皆取實，己獨取虛，無藏也故有餘，巋然而有餘。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-42_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-42\",\"order\":2,\"canonicalText\":\"其行身也，徐而不費，無為也而笑巧；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-43_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-43\",\"order\":1,\"canonicalText\":\"人皆求福，己獨曲全，曰苟免於咎。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-43_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-43\",\"order\":2,\"canonicalText\":\"以深為根，以約為紀，曰堅則毀矣，銳則挫矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-43_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-43\",\"order\":3,\"canonicalText\":\"常寬容於物，不削於人，可謂至極。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-44_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-44\",\"order\":1,\"canonicalText\":\"關尹、老聃乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-44_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-44\",\"order\":2,\"canonicalText\":\"古之博大真人哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-45_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-45\",\"order\":1,\"canonicalText\":\"寂漠無形，變化無常，死與生與，天地並與，神明往與！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-45_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-45\",\"order\":2,\"canonicalText\":\"芒乎何之，忽乎何適，萬物畢羅，莫足以歸，古之道術有在於是者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-46_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-46\",\"order\":1,\"canonicalText\":\"莊周聞其風而悅之，以謬悠之說，荒唐之言，無端崖之辭，時恣縱而不儻，不以觭見之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-46_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-46\",\"order\":2,\"canonicalText\":\"以天下為沈濁，不可與莊語，以巵言為曼衍，以重言為真，以寓言為廣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-47_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-47\",\"order\":1,\"canonicalText\":\"獨與天地精神往來，而不敖倪於萬物，不譴是非，以與世俗處。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-47_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-47\",\"order\":2,\"canonicalText\":\"其書雖瓌瑋，而連犿無傷也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-47_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-47\",\"order\":3,\"canonicalText\":\"其辭雖參差，而諔詭可觀。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-47_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-47\",\"order\":4,\"canonicalText\":\"彼其充實不可以已，\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-48_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-48\",\"order\":1,\"canonicalText\":\"上與造物者遊，而下與外死生無終始者為友。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-48_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-48\",\"order\":2,\"canonicalText\":\"其於本也，弘大而闢，深閎而肆，其於宗也，可謂調適而上遂矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-49_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-49\",\"order\":1,\"canonicalText\":\"雖然，其應於化而解於物也，其理不竭，其來不蛻，芒乎昧乎，未之盡者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-50_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-50\",\"order\":1,\"canonicalText\":\"惠施多方，其書五車，其道舛駁，其言也不中。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-50_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-50\",\"order\":2,\"canonicalText\":\"歷物之意，曰：「至大無外，謂之大一；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-50_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-50\",\"order\":3,\"canonicalText\":\"至小無內，謂之小一。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-51_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-51\",\"order\":1,\"canonicalText\":\"無厚，不可積也，其大千裏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-51_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-51\",\"order\":2,\"canonicalText\":\"天與地卑，山與澤平。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-51_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-51\",\"order\":3,\"canonicalText\":\"日方中方睨，物方生方死。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-51_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-51\",\"order\":4,\"canonicalText\":\"大同而與小同異，此之謂小同異；\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-51_s-5\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-51\",\"order\":5,\"canonicalText\":\"萬物畢同畢異，此之謂大同異。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-52_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-52\",\"order\":1,\"canonicalText\":\"南方無窮而有窮，今日適越而昔來。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-52_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-52\",\"order\":2,\"canonicalText\":\"連環可解也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-52_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-52\",\"order\":3,\"canonicalText\":\"我知天下之中央，燕之北越之南是也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-52_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-52\",\"order\":4,\"canonicalText\":\"氾愛萬物，天地一體也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-52_s-5\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-52\",\"order\":5,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-53_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-53\",\"order\":1,\"canonicalText\":\"惠施以此為大，觀於天下而曉辯者，天下之辯者相與樂之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-53_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-53\",\"order\":2,\"canonicalText\":\"卵有毛，雞三足，郢有天下，犬可以為羊，馬有卵，丁子有尾，\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-54_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-54\",\"order\":1,\"canonicalText\":\"火不熱，山出口，輪不蹍地，目不見，指不至，至不絕，龜長於蛇，矩不方，規不可以為圓，鑿不圍枘，飛鳥之景未嘗動也，\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-55_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-55\",\"order\":1,\"canonicalText\":\"鏃矢之疾而有不行不止之時，狗非犬，黃馬驪牛三，白狗黑，孤駒未嘗有母，一尺之捶，日取其半，萬世不竭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-55_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-55\",\"order\":2,\"canonicalText\":\"辯者以此與惠施相應，終身無窮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-56_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-56\",\"order\":1,\"canonicalText\":\"桓團、公孫龍辯者之徒，飾人之心，易人之意，能勝人之口，不能服人之心，辯者之囿也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-56_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-56\",\"order\":2,\"canonicalText\":\"惠施日以其知與人之辯，特與天下之辯者為怪，此其柢也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-57_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-57\",\"order\":1,\"canonicalText\":\"然惠施之口談，自以為最賢，曰天地其壯乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-57_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-57\",\"order\":2,\"canonicalText\":\"施存雄而無術。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-57_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-57\",\"order\":3,\"canonicalText\":\"南方有倚人焉曰黃繚，問天地所以不墜不陷，風雨雷霆之故。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-58_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-58\",\"order\":1,\"canonicalText\":\"惠施不辭而應，不慮而對，徧為萬物說，說而不休，多而無已，猶以為寡，益之以怪。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-58_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-58\",\"order\":2,\"canonicalText\":\"以反人為實而欲以勝人為名，是以與眾不適也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-59_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-59\",\"order\":1,\"canonicalText\":\"弱於德，強於物，其塗隩矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-59_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-59\",\"order\":2,\"canonicalText\":\"由天地之道觀惠施之能，其猶一蚊一䖟之勞者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-59_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-59\",\"order\":3,\"canonicalText\":\"其於物也何庸！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-59_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-59\",\"order\":4,\"canonicalText\":\"夫充一尚可，曰愈貴道，幾矣！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-60_s-1\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-60\",\"order\":1,\"canonicalText\":\"惠施不能以此自寧，散於萬物而不厭，卒以善辯為名。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-60_s-2\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-60\",\"order\":2,\"canonicalText\":\"惜乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-60_s-3\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-60\",\"order\":3,\"canonicalText\":\"惠施之才，駘蕩而不得，逐萬物而不反，是窮響以聲，形與影競走也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"zhuangzi_ch-33_p-60_s-4\",\"workId\":\"zhuangzi\",\"chapterId\":\"zhuangzi_ch-33\",\"passageId\":\"zhuangzi_ch-33_p-60\",\"order\":4,\"canonicalText\":\"悲夫！\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
